//! 🧪️ The canonical native history command retains original selected order and the same receiving recipient through Undo and Redo.
use super::*;
#[test]fn original_native_history_undo_redo_publish_original_order_and_close(){
 use store::os_store::{ArtifactNativeVcsCommand,ArtifactNativeVcsRequest,ArtifactNativeVcsPhase};let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let mut caller=caller();let mut decoder=OriginalJobDecodeOwner::empty();let mut store=native_document_store(&mut caller,&mut decoder);publish_original_fixture(&mut store,&mut caller,&mut decoder);let g=RetainedCloneGrant{maximum_copy_bytes:32768,maximum_capacity_bytes:16<<20,..TURN};
 for step in law["steps"].as_array().unwrap(){let mut request=Some(match step["mode"].as_str().unwrap(){"undo"=>ArtifactNativeVcsRequest::Undo{lane:store::os_store::store_schema::HistoryLane::Document,policy:protocol::UndoPolicy::TransformAgainstConcurrent},"redo"=>ArtifactNativeVcsRequest::Redo{lane:store::os_store::store_schema::HistoryLane::Document},_=>unreachable!()});let mut command=None;let d=ArtifactNativeVcsCommand::<State,Mutation>::capture_demands();assert!(d.copy_bytes<=32768&&d.capacity_bytes<=16<<20,"command header exceeds mounted policy {d:?}");for axis in law["deniedAxes"].as_array().unwrap(){let mut denied=g;match axis.as_str().unwrap(){"items"=>denied.maximum_items=0,"copy"=>denied.maximum_copy_bytes=d.copy_bytes-1,"capacity"=>denied.maximum_capacity_bytes=d.capacity_bytes-1,"depth"=>denied.maximum_depth=0,_=>unreachable!()}turn(&mut caller,&mut decoder,denied,|cx|{assert!(!store.admit_native_vcs_command(&mut request,cx,&mut command)?);Ok(())});assert!(command.is_none()&&request.is_some());}
turn(&mut caller,&mut decoder,g,|cx|{assert!(store.admit_native_vcs_command(&mut request,cx,&mut command)?);Ok(())});let mut foreign=OriginalJobDecodeOwner::empty();turn(&mut caller,&mut foreign,g,|cx|{assert!(store.advance_native_vcs_command(command.as_mut().unwrap(),cx).is_err());assert!(store.close_native_vcs_command(command.as_mut().unwrap(),cx).is_err());Ok(())});assert!(foreign.terminal_is_empty());let before=store.generation();for index in 0..262144{let progress=turn(&mut caller,&mut decoder,g,|cx|store.advance_native_vcs_command(command.as_mut().unwrap(),cx));assert!(command.as_ref().unwrap().borrow_failure().is_none(),"original history failure {:?}",command.as_ref().unwrap().borrow_failure());if progress.phase==ArtifactNativeVcsPhase::AwaitingAck{break}assert!(index<262143,"original native {} stalled at {:?}",step["mode"],progress.phase);}let mut result=None;turn(&mut caller,&mut decoder,g,|cx|{assert!(store.take_native_vcs_result(command.as_mut().unwrap(),cx,&mut result)?);Ok(())});assert!(result.unwrap().selected.is_some());assert_eq!(store.generation(),before+1);assert_eq!(store.snapshot().unwrap().zoom,step["expected"].as_f64().unwrap());assert_eq!(store.parts_ref().log.applied_edit_ids.len(),step["applied"].as_u64().unwrap()as usize);assert_eq!(store.parts_ref().log.redo_edit_ids.len(),step["redo"].as_u64().unwrap()as usize);turn(&mut caller,&mut decoder,g,|cx|{assert!(store.ack_native_vcs_command(command.as_mut().unwrap(),cx)?);Ok(())});for index in 0..262144{if turn(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|store.close_native_vcs_command(command.as_mut().unwrap(),cx))){break}assert!(index<262143,"original history command close stalled");}assert!(command.as_ref().unwrap().terminal_is_empty());}
 for index in 0..1048576{if store.close_owned_store_terminal_is_empty(){break}turn(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|{let d=store.close_owned_demands(4096)?;close_original_retained_step(cx,d,|grant|store.close_owned_store_step(grant))?;Ok(())}));assert!(index<1048575);}release_native_store_box(store,&mut caller,&mut decoder);while !decoder.terminal_is_empty(){caller.turn(g,|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(4096)?;close_original_retained_step(cx,d,|grant|decoder.close_step(grant))?;Ok(())})).unwrap();}caller.retire(g);
}

fn publish_original_fixture(store:&mut store::ConfigStore<State,Mutation>,caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner){type Publisher=store::os_store::original_replay_publication::OriginalReplayPublication<State,Mutation>;let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let mut finished=Some(crate::original_replay_publication::prepare_report(store,caller,decoder));let mut request=Some(store::HistoryFinalization::Overwrite);let mut publisher=None;let g=RetainedCloneGrant{maximum_copy_bytes:32768,maximum_capacity_bytes:16<<20,..TURN};turn(caller,decoder,g,|cx|{assert!(Publisher::admit(store,&mut finished,&mut request,cx,&mut publisher)?);Ok(())});for index in 0..262144{if turn(caller,decoder,g,|cx|publisher.as_mut().unwrap().advance(store,cx)){break}assert!(index<262143);}turn(caller,decoder,g,|cx|{assert!(publisher.as_mut().unwrap().publish(store,cx)?);Ok(())});let mut receipt=None;turn(caller,decoder,g,|cx|{assert!(publisher.as_mut().unwrap().take_receipt(cx,&mut receipt)?);Ok(())});turn(caller,decoder,g,|cx|{assert!(publisher.as_mut().unwrap().acknowledge(cx)?);Ok(())});for index in 0..262144{if turn(caller,decoder,g,|cx|cx.with_original_retirement(|cx|publisher.as_mut().unwrap().close_step(store,cx))){break}assert!(index<262143);}turn(caller,decoder,g,|cx|cx.with_original_retirement(|cx|{let d=Publisher::boxed_release_demands();close_original_retained_step(cx,d,|_|{publisher=None;Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,released_bytes:d.release_bytes,..Default::default()}))})?;Ok(())}));assert_eq!(store.snapshot().unwrap().zoom,law["published"].as_f64().unwrap());}

#[test]fn original_native_history_cancellation_returns_each_selected_source_with_exact_close_quote(){
 use store::os_store::{ArtifactNativeVcsRequest,ArtifactNativeVcsPhase};let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for cut in law["cancelCuts"].as_array().unwrap(){let cut=cut.as_u64().unwrap()as usize;let mut caller=caller();let mut decoder=OriginalJobDecodeOwner::empty();let mut store=native_document_store(&mut caller,&mut decoder);publish_original_fixture(&mut store,&mut caller,&mut decoder);let g=RetainedCloneGrant{maximum_copy_bytes:32768,maximum_capacity_bytes:16<<20,..TURN};let mut request=Some(ArtifactNativeVcsRequest::Undo{lane:store::os_store::store_schema::HistoryLane::Document,policy:protocol::UndoPolicy::TransformAgainstConcurrent});let mut command=None;turn(&mut caller,&mut decoder,g,|cx|{assert!(store.admit_native_vcs_command(&mut request,cx,&mut command)?);Ok(())});for _ in 0..cut{let p=turn(&mut caller,&mut decoder,g,|cx|store.advance_native_vcs_command(command.as_mut().unwrap(),cx));if p.phase==ArtifactNativeVcsPhase::AwaitingAck{break}}caller.cancel().cancel_now();for index in 0..262144{if command.as_ref().unwrap().terminal_is_empty(){break}let d=store.native_vcs_command_close_demands(command.as_ref().unwrap(),4096).unwrap();assert!(d.copy_bytes<=32768&&d.capacity_bytes<=16<<20,"actual history close exceeds mounted policy {d:?}");let closing=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};turn(&mut caller,&mut decoder,closing,|cx|cx.with_original_retirement(|cx|store.close_native_vcs_command(command.as_mut().unwrap(),cx)));assert!(index<262143,"native selected command cancellation stalled at {cut} quote {d:?}");}assert!(command.as_ref().unwrap().terminal_is_empty());for index in 0..1048576{if store.close_owned_store_terminal_is_empty(){break}turn(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|{let d=store.close_owned_demands(4096)?;close_original_retained_step(cx,d,|grant|store.close_owned_store_step(grant))?;Ok(())}));assert!(index<1048575);}release_native_store_box(store,&mut caller,&mut decoder);while !decoder.terminal_is_empty(){caller.turn(g,|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(4096)?;close_original_retained_step(cx,d,|grant|decoder.close_step(grant))?;Ok(())})).unwrap();}caller.retire(g);}
}

#[test]fn original_native_history_failure_projects_every_original_field_without_mirrors(){
 use store::os_store::ArtifactOriginalVcsFailure;let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let expected=&law["failure"];let row=&expected["original"]["messages"][0];let message=protocol::MutationMessage{level:semio_framework_diagnostic::Severity::Error,code:semio_framework_diagnostic::FaultCode(row["code"].as_str().unwrap().into()),message:row["message"].as_str().unwrap().into(),target:vec![row["target"][0].as_str().unwrap().into()],op_index:Some(row["opIndex"].as_u64().unwrap()as u32)};let text=message.message.as_ptr();let target=message.target[0].as_ptr();let mut original=Some(ArtifactOriginalVcsFailure::from(store::os_vcs::VcsError::Rejected{policy:protocol::MergePolicy::Vigilant,messages:vec![message]}));let mut caller=caller();let mut decoder=OriginalJobDecodeOwner::empty();let mut output=None;turn(&mut caller,&mut decoder,TURN,|cx|{output=semio_framework_job::admit_original_domain_failure(&mut original,cx)?;Ok(())});assert!(original.is_none());let domain=output.as_ref().unwrap().primary_domain().unwrap();let projection=domain.projection();for(path,expected,pointer)in[(&[0][..],"rejected",None),(&[1,0][..],"Vigilant",None),(&[1,1,0,1][..],row["code"].as_str().unwrap(),None),(&[1,1,0,2][..],row["message"].as_str().unwrap(),Some(text)),(&[1,1,0,3,0][..],row["target"][0].as_str().unwrap(),Some(target))]{let(view,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||projection.projection_view(path).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let semio_framework_job::OriginalDomainView::IntrinsicText(actual)=view else{panic!("original failure text projection retained its type")};assert_eq!(actual,expected);if let Some(pointer)=pointer{assert_eq!(actual.as_ptr(),pointer);}}assert_eq!(projection.projection_key(&[1],1).unwrap(),"messages");crate::close_typed(output,&mut caller,&mut decoder);while !decoder.terminal_is_empty(){caller.turn(TURN,|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(4096)?;close_original_retained_step(cx,d,|grant|decoder.close_step(grant))?;Ok(())})).unwrap();}caller.retire(TURN);
}
